<?php $statusLabels=['complete'=>['Completo','connection-connected','fa-circle-check'],'missing_unit'=>['Sem unidade','connection-rejected','fa-building-circle-exclamation'],'missing_asaas'=>['Pendente Asaas','connection-rejected','fa-wallet'],'missing_moodle'=>['Pendente Moodle','connection-awaiting_official_api','fa-graduation-cap'],'moodle_review'=>['Revisar Moodle','connection-awaiting_official_api','fa-triangle-exclamation']]; ?>
<header class="section-heading"><div><span class="status">Alunos</span><h1>Consultar</h1><p class="meta">Todos os alunos ativos, com o estado das integrações claramente identificado.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/finance/customers/create"><i class="fa-solid fa-user-plus"></i> Novo aluno</a></header>
<form method="get" action="<?= $escape($basePath) ?>/students" class="contact-filters"><input name="q" value="<?= $escape($search) ?>" placeholder="Nome, e-mail, CPF ou usuário do Moodle"><button type="submit">Pesquisar</button><?php if($search!==''):?><a class="button-secondary" href="<?= $escape($basePath) ?>/students">Limpar</a><?php endif;?></form>
<section class="card"><div class="table-responsive"><table><thead><tr><th>Aluno</th><th>CPF</th><th>Unidade</th><th>Asaas</th><th>Moodle</th><th>Cursos</th><th>Integração</th><th>Ação</th></tr></thead><tbody><?php if($students===[]):?><tr><td colspan="8">Nenhum aluno ativo encontrado.</td></tr><?php endif;?><?php foreach($students as$student):?><?php [$label,$class,$icon]=$statusLabels[$student['integration_status']]??['Em revisão','connection-awaiting_official_api','fa-triangle-exclamation'];?><tr><td><strong><?= $escape($student['name']) ?></strong><br><small><?= $escape($student['email']?:'Sem e-mail') ?></small></td><td><?= $escape($student['cpf_cnpj']?:'Não informado') ?></td><td><?= $escape($student['unit_name']?:'Sem unidade') ?></td><td><?php if($student['asaas_customer_id']):?><span class="connection-badge connection-connected"><i class="fa-solid fa-check"></i>&nbsp; Vinculado</span><?php else:?><span class="connection-badge connection-rejected">Pendente</span><?php endif;?></td><td><?php if((int)$student['moodle_linked']===1):?><span class="connection-badge connection-connected"><i class="fa-solid fa-check"></i>&nbsp; <?= $escape($student['username']) ?></span><?php elseif($student['moodle_user_id']):?><span class="connection-badge connection-awaiting_official_api">Revisar vínculo</span><?php else:?><span class="connection-badge connection-awaiting_official_api">Não vinculado</span><?php endif;?></td><td><?= (int)$student['active_courses'] ?></td><td><span class="connection-badge <?= $escape($class) ?>"><i class="fa-solid <?= $escape($icon) ?>"></i>&nbsp; <?= $escape($label) ?></span></td><td><a class="button-secondary button-small" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$student['id'] ?>"><i class="fa-solid fa-eye"></i> Abrir</a></td></tr><?php endforeach;?></tbody></table></div></section>
